esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// node_disk_io_time_seconds_total is a counter of device busy time, so its per-second rate
// approximates utilisation (1.0 = busy for the whole window). Same metric and aggregation
// as the "Disk IO Time vs Disk Discard Time" dashboard panel.
| STATS
    `IO Time Rate` = SUM(RATE(node_disk_io_time_seconds_total)),
    `Weighted IO Time Rate` = SUM(RATE(node_disk_io_time_weighted_seconds_total))
  BY resource.attributes.supabase_project_ref, attributes.device
// Per-device rates can round marginally outside [0, 1], so clamp before presenting a %.
| EVAL `Disk IO Utilisation %` = ROUND(CLAMP(`IO Time Rate`, 0.0, 1.0) * 100, 1)
// Weighted time divided by busy time approximates average queue depth; above 1 means
// requests are queueing behind the device rather than merely keeping it busy.
| EVAL `Avg Queue Depth` = ROUND(`Weighted IO Time Rate` / CLAMP(`IO Time Rate`, 0.001, 1.0), 2)
// Lower on burstable compute tiers, where sustained high IO silently burns a credit balance.
| WHERE `Disk IO Utilisation %` >= 90
// One row per device, so the alert instance key includes it.
| EVAL alert_instance = CONCAT(resource.attributes.supabase_project_ref, " / ", attributes.device)
| SORT `Disk IO Utilisation %` DESC
